package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class TakeStatement {
    // Records the person's due-total now and binds each of their counting claims to its figure now;
    // the rest of their claims are left unbound.
    public void take(@Val Person person, Claims claims, Rates rates, Settings settings, Sheets sheets, Statements statements,
            Out<Statement> statementOut) {
        statements.lock(person.id());
        LocalDate today = sheets.today(person.sheetId());
        Map<Long, BigDecimal> figures = new LinkedHashMap<>();
        for (Claim claim : claims.list(person.sheetId())) {
            if (claim.personId() == person.id()
                    && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.SETTLED)) {
                figures.put(claim.id(), figure(claim, person, rates, settings));
            }
        }
        BigDecimal total = figures.values().stream().filter(Objects::nonNull)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        // With no rate today and no figure, the due-total is n/a.
        boolean none = rates.on(person.sheetId(), person.grade(), today) == null
                && figures.values().stream().allMatch(Objects::isNull);
        claims.bind(person.sheetId(), person.id(), figures);
        Statement statement = new Statement(person.sheetId(), person.id(), none ? "n/a" : total.toPlainString(),
                figures.size(), today);
        statements.add(statement);
        statementOut.set(statement);
    }

    /**
     * The claim's figure now (null when it has none): a settled claim's frozen due, otherwise the figure the
     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, half to even, raised to the floor.
     */
    private static BigDecimal figure(Claim claim, Person person, Rates rates, Settings settings) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.grade(), claim.date());
        return rate == null ? null : settings.floored(claim.sheetId(), claim.amount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class ApplyClaimStatus {
    // Stored only if the claim still has the status it was loaded with, so two users cannot both move it.
    public void apply(@PathVariable("status") String status, @Val Claim claim, Claims claims,
            People people, Rates rates, Settings settings, ServerHttpConnection connection,
            Out<ClaimResponse> responseOut) throws ClaimStatusRefusedException, ClaimOverLimitException {
        ClaimStatus next;
        try {
            next = ClaimStatus.valueOf(status.trim().toUpperCase());
        } catch (IllegalArgumentException e) {
            throw new ClaimStatusRefusedException("Not a claim status: " + status);
        }
        String user = Audit.user(connection).trim();
        // Four eyes: the user who opened a claim cannot settle it.
        if (next == ClaimStatus.SETTLED && claim.openedBy() != null && claim.openedBy().equals(user)) {
            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it.");
        }
        if (!claim.status().allows(next)) {
            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
        }
        BigDecimal due = due(claim, people, rates, settings);
        // A clerk settles only a claim whose due is at or below the clerk limit; a due of n/a is within
        // any limit, and a steward settles anything.
        if (next == ClaimStatus.SETTLED && due != null) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && due.compareTo(limit) > 0
                    && !Settings.STEWARD.equals(settings.role(claim.sheetId(), user))) {
                throw new ClaimOverLimitException(
                        "A clerk cannot settle a claim whose due " + due.toPlainString() + " is above the clerk limit "
                                + limit.toPlainString() + ".");
            }
        }
        Claim changed = claims.changeStatus(claim, next, due, user);
        if (changed == null) {
            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
        }
        responseOut.set(ClaimResponse.from(changed));
    }

    /**
     * The claim's due now: the figure its person's last statement bound it to, otherwise its amount times its
     * person's grade's rate on the claim's date, half to even, raised to the floor; null when none applies.
     */
    private static BigDecimal due(Claim claim, People people, Rates rates, Settings settings) {
        if (claim.stated()) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person == null) {
            return null;
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.grade(), claim.date());
        return rate == null ? null : settings.floored(claim.sheetId(), claim.amount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of sheets. A sheet never stored is an empty sheet whose today is the real date. */
@Repository
public class Sheets {

    private final JdbcTemplate jdbc;

    public Sheets(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Sheet find(String id) {
        List<LocalDate> today = jdbc.query("SELECT today_date FROM sheet WHERE id = ?",
                (rs, n) -> rs.getObject(1, LocalDate.class), id);
        return new Sheet(id, today.isEmpty() ? LocalDate.now() : today.get(0));
    }

    /** The sheet's today: use this, never the real clock, for anything that depends on the date. */
    public LocalDate today(String id) {
        return find(id).today();
    }

    public void save(Sheet sheet) {
        jdbc.update("MERGE INTO sheet (id, today_date) KEY (id) VALUES (?, ?)", sheet.id(), sheet.today());
    }
}
